import { config } from './config.js';
import { buildReport, defaultSettings } from './analytics.js';
import { demoSnapshot } from './demo-data.js';

const $ = (selector, base = document) => base.querySelector(selector);
const $$ = (selector, base = document) => [...base.querySelectorAll(selector)];
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[char]));
const attr = value => escape(value);
const human = value => String(value ?? '').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
const num = value => value === null || value === undefined || !Number.isFinite(Number(value)) ? '—' : new Intl.NumberFormat('en-GB', { maximumFractionDigits: 0 }).format(Number(value));
const dec = (value, places = 1) => value === null || value === undefined || !Number.isFinite(Number(value)) ? '—' : Number(value).toFixed(places);
const pct = value => value===null||value===undefined||!Number.isFinite(Number(value))?'—':`${dec(value)}%`;
const duration = value => value === null || value === undefined ? '—' : `${Math.floor(Number(value) / 60)}m ${Math.round(Number(value) % 60)}s`;
const date = (value, time = false) => { if (!value || Number.isNaN(new Date(value).getTime())) return '—'; return new Intl.DateTimeFormat('en-GB', { timeZone:config.timezone, day:'numeric', month:'short', ...(time ? {hour:'2-digit',minute:'2-digit'} : {year:'numeric'}) }).format(new Date(value)); };
const money = (value, currency = 'EUR') => { if(value === null || value === undefined) return '—'; try { return new Intl.NumberFormat('en-GB', { style:'currency',currency,maximumFractionDigits:0 }).format(value); } catch { return `${num(value)} ${escape(currency)}`; } };
const values = value => Object.entries(value || {}).map(([currency,amount])=>money(amount,currency)).join(' · ') || '—';
const rate = (a,b) => b ? a/b*100 : null;
const textValue = value => value === null || value === undefined || value === '' ? '—' : typeof value === 'object' ? JSON.stringify(value) : String(value);
const makeAction = (action, value, text, cls = 'row-link', extra = '') => `<button type="button" class="${cls}" data-action="${attr(action)}" data-value="${attr(value)}" ${extra}>${text}</button>`;
const statuses = ['NEW','ENGAGED','HIGH INTENT','CONTACTED','OPPORTUNITY','CUSTOMER','LOST'];
const nav = [
 ['overview','Overview','<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>'],
 ['traffic','Traffic','<path d="M3 17l6-6 4 3 8-10M16 4h5v5M3 21h18"/>'],
 ['funnels','Funnels','<path d="M3 4h18l-7 8v7l-4 2v-9z"/>'],
 ['configurators','Configurators','<path d="M12 3l9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9"/>'],
 ['leads','Leads','<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0112 0v2M16 5a3 3 0 010 6M17 15a5 5 0 014 5"/>'],
 ['campaigns','Campaigns','<path d="M3 10v6h4l11 4V5L7 10zM7 16l2 5h3M21 9v7"/>'],
 ['journeys','Journeys','<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M5 7v7a5 5 0 005 5h7M9 5h7a3 3 0 010 6h-3"/>'],
 ['live','Live','<path d="M2 12h4l3-8 5 16 3-8h5"/>'],
 ['insights','Insights','<path d="M9 18h6M9 21h6M8 15c-5-4-2-12 4-12s9 8 4 12l-1 2H9z"/>'],
 ['settings','Settings','<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>'],
];
const descriptions = {
 overview:['YOUR COMMERCIAL PICTURE','From first visit to serious interest.'],traffic:['UNDERSTAND YOUR AUDIENCE','Where visitors come from, and what keeps them interested.'],funnels:['FROM INTEREST TO ACTION','See where people progress, pause and leave.'],configurators:['PRODUCT INTEREST','Understand what your next customers are building.'],leads:['YOUR COMMERCIAL PIPELINE','Turn volunteered contact details into useful conversations.'],campaigns:['MEASURE WHAT MATTERS','See which campaigns generate genuine commercial interest.'],journeys:['FOLLOW THE STORY','Connect each visit, configuration and conversation.'],live:['HAPPENING NOW','Visitors active within the last five minutes.'],insights:['SIGNALS WORTH YOUR ATTENTION','Useful patterns and problems, drawn from recorded activity.'],settings:['WORKSPACE PREFERENCES','Manage scoring, reporting and collection settings.'],
};
const filterDefaults = {preset:'Last 30 Days',from:'',to:'',compare:true,source:'All',campaign:'All',country:'All',device:'All',category:'All',model:'All',configurator:'All',visitorType:'All',identity:'All',status:'All',intent:'All',query:''};
const state = {tab:'overview',mode:'live',snapshot:null,report:null,filters:{...filterDefaults},metrics:['visitors','starts'],configuratorTab:'led',leadTab:'all',token:null,expiresAt:null,lastUpdated:null,drawerFocus:null,toastTimer:null,requestVersion:0,lastError:null};

async function api(action, body = {}) {
 const response = await fetch(config.endpoint,{method:'POST',headers:{'Content-Type':'application/json',...(state.token?{'X-Reports-Session':state.token}:{})},body:JSON.stringify({action,...body}),signal:AbortSignal.timeout(45000)});
 let result; try { result=await response.json(); } catch { throw new Error('The reporting service returned an unreadable response.'); }
 if(!response.ok || result?.error) { if(response.status===401&&action!=='login') signOut(false); throw new Error(typeof result?.error==='string'?result.error:(result?.error?.message||`Reporting service unavailable (${response.status}).`)); }
 return result;
}
function sessionSave() { try{sessionStorage.setItem(config.sessionKey,JSON.stringify({token:state.token,expires_at:state.expiresAt}));}catch{} }
function sessionClear(){try{sessionStorage.removeItem(config.sessionKey);}catch{}}
function banner(message, action = '') { const target=$('#app-banner');target.hidden=!message;target.innerHTML=message?`<span>${escape(message)}</span>${action}`:''; }
function updateBanner(){
 if(state.lastError){banner(`Refresh failed: ${state.lastError} Showing the last successfully loaded report from ${date(state.lastUpdated,true)}.`);return;}
 if(state.snapshot?.meta?.truncated){banner(state.snapshot.meta.warning||'The reporting row limit was reached. These reports are partial; totals and comparisons may be incomplete.');return;}
 if(state.mode==='demo'){banner('Demonstration data — all visitors, contacts and commercial results shown here are fictional. Live website tracking has not been enabled.',makeAction('return-login','','Open live reports →','text-button'));return;}
 if(!state.snapshot?.events?.length){banner('The reports workspace is ready. No live website events have been collected yet; tracking remains separate from the public site.',makeAction('demo','','Explore demo →','text-button'));return;}
 banner('');
}
function toast(message) { clearTimeout(state.toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;state.toastTimer=setTimeout(()=>$('#toast').hidden=true,4500); }
function empty(title='No recorded activity', detail='There are no observations for the current filters. Try a wider date range or clear your filters.') { return `<div class="empty-state"><span class="empty-symbol" aria-hidden="true">◇</span><strong>${escape(title)}</strong><p>${escape(detail)}</p></div>`; }
function panel(title, body, options={}) { return `<section class="panel ${options.className||''}"><div class="panel-head"><div><h2 class="panel-title">${escape(title)}</h2>${options.description?`<p class="panel-description">${escape(options.description)}</p>`:''}</div>${options.action||''}</div>${options.table?body:`<div class="panel-body">${body}</div>`}</section>`; }
function section(title, body) { return `<section class="detail-section"><h3>${escape(title)}</h3>${body}</section>`; }
function field(label,value) { return `<div class="detail-field"><span>${escape(label)}</span>${escape(textValue(value))}</div>`; }
function detailGrid(fields){return `<div class="detail-grid">${fields.map(([key,value])=>field(key,value)).join('')}</div>`;}
function badge(status, mode='') { const s=String(status||'NEW');const cls=mode||(s.includes('HIGH')||s==='CUSTOMER'?'green':s==='LOST'?'neutral':s==='OPPORTUNITY'?'amber':'');return `<span class="badge ${cls}">${escape(s)}</span>`; }
function score(value){return `<span class="score ${Number(value)>=60?'high':''}">${num(value)}</span>`;}
function comparison(key){ if(!state.filters.compare)return '';const current=state.report?.metrics?.[key];const previous=state.report?.previousMetrics?.[key];if(previous===0&&current>0)return '<span class="delta-flat">New this period</span>';if(previous===0&&current===0)return '<span class="delta-flat">No change</span>';if(previous===null||previous===undefined||current===null)return '<span class="delta-flat">No comparison</span>';const d=(current-previous)/previous*100;return `<span class="${d>0?'delta-up':d<0?'delta-down':'delta-flat'}">${d>0?'↗ +':d<0?'↘ ':''}${dec(d)}%</span><span class="delta-period">vs previous period</span>`;}
function kpis(items) { return `<div class="kpi-grid">${items.map(([label,key,format,tip],i)=>`<div class="kpi ${i===4?'highlight':''}"><div class="kpi-label" title="${attr(tip||label)}">${escape(label)}<span class="kpi-icon" aria-hidden="true">${['◉','↶','◇','□','♧','↗'][i%6]}</span></div><div class="kpi-value">${format?format(state.report.metrics[key]):num(state.report.metrics[key])}</div><div class="kpi-delta">${comparison(key)}</div></div>`).join('')}</div>`; }
function table(columns,rows,options={}) { if(!rows?.length)return empty(options.emptyTitle||'No matching records',options.emptyDetail);return `<div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th scope="col" class="${c.num?'num':''}" ${c.title?`title="${attr(c.title)}"`:''}>${escape(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(c=>`<td class="${c.num?'num':''}">${c.render?c.render(row):escape(textValue(row[c.key]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${options.caption?`<div class="table-caption"><span>${escape(options.caption)}</span><span>${num(rows.length)} records</span></div>`:''}`; }
function breakdown(rows,dimension,metric='visitors',color='var(--accent)',limit=6) { if(!rows?.length)return empty();const max=Math.max(...rows.map(r=>Number(r[metric])||0),1);return `<div class="breakdown-list">${rows.slice(0,limit).map(r=>`<button class="bar-row" data-action="filter" data-dimension="${attr(dimension)}" data-value="${attr(r.name)}" title="Show ${attr(r.name)}"><span>${escape(r.name)}</span><span class="bar-track"><span class="bar-fill" style="width:${Math.max(0,Number(r[metric])||0)/max*100}%;background:${color}"></span></span><span class="bar-value">${num(r[metric])}</span></button>`).join('')}</div><div class="bar-caption"><span>${escape(human(metric))} by ${escape(dimension==='category'?'simulator':dimension)}</span><span>Click a row to explore ↗</span></div>`; }
function funnel(rows,type='website',full=false) { if(!rows?.length||!rows[0]?.count)return empty('No funnel activity yet','Once visitors use the configurators, their step-by-step progress will appear here.');const max=rows[0].count;return `<div class="funnel-total-note">Ordered sessions · % of ${full?'previous step and ':''}starting population</div><div class="funnel-list">${rows.map((r,i)=>`<div class="funnel-row"><span class="funnel-step">${escape(r.label)}</span><span class="funnel-bar-track"><span class="funnel-bar" style="width:${Math.max(1,r.count/max*100)}%;opacity:${1-i*.055}"></span></span><span class="funnel-count">${num(r.count)}</span><span class="funnel-rate" title="${pct(r.totalPct)} of starting population; ${pct(r.previousPct)} of previous step">${pct(r.totalPct)}</span>${full&&i>0?`<button class="funnel-loss" data-action="dropoff" data-value="${attr(type)}:${i}" title="Inspect sessions that did not reach this step">${pct(r.previousPct)} of previous · ${num(r.lost)} did not continue (${pct(r.dropPct)}) ↗</button>`:''}</div>`).join('')}</div>`; }
function renderChart(rows) {const metrics={visitors:['Visitors','#f04457'],sessions:['Sessions','#b6a0ed'],pageViews:['Page views','#7a93b6'],starts:['Configurator starts','#7ca1f7'],completed:['Completed','#d7b574'],leads:['Leads','#66cf9d'],enquiries:['Enquiries','#e698c1']};const legend=`<div class="chart-legend">${Object.entries(metrics).map(([key,[label,color]])=>`<label><input type="checkbox" data-chart-metric="${key}" ${state.metrics.includes(key)?'checked':''}><span><i class="legend-dot" style="background:${color}"></i>${label}</span></label>`).join('')}</div>`;if(!rows?.length)return legend+empty();const width=1000,height=210,left=35,right=10,top=13,bottom=27,max=Math.max(1,...rows.flatMap(r=>state.metrics.map(m=>Number(r[m])||0)));const chartWidth=width-left-right,chartHeight=height-top-bottom;const x=i=>left+(rows.length>1?i/(rows.length-1):.5)*chartWidth;const y=v=>top+chartHeight-(v/max)*chartHeight;const gridValues=[...new Set([0,.25,.5,.75,1].map(t=>Math.round(max*t)))];const grids=gridValues.map(value=>`<line x1="${left}" x2="${width-right}" y1="${y(value)}" y2="${y(value)}" stroke="#2a2d34" stroke-dasharray="2 5"/><text class="chart-axis" x="${left-9}" y="${y(value)+3}" text-anchor="end">${num(value)}</text>`).join('');const ticks=[...new Set([0,Math.floor((rows.length-1)*.25),Math.floor((rows.length-1)*.5),Math.floor((rows.length-1)*.75),rows.length-1])];const axis=ticks.map(i=>`<text class="chart-axis" x="${x(i)}" y="${height-6}" text-anchor="${i===0?'start':i===rows.length-1?'end':'middle'}">${escape(String(rows[i].date).slice(5).replace('-','/'))}</text>`).join('');const paths=state.metrics.map(m=>{const points=rows.map((r,i)=>`${x(i)},${y(Number(r[m])||0)}`).join(' ');return `<polyline points="${points}" stroke="${metrics[m][1]}" stroke-width="2.3" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`;}).join('');return `${legend}<div class="chart-container" id="activity-chart"><svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Daily visitor and conversion activity across the selected period">${grids}${axis}${paths}</svg><div class="chart-hover" hidden></div></div><p class="panel-note">Daily counts · ${state.metrics.map(m=>metrics[m][0].toLowerCase()).join(', ')} · Hover for exact values</p><details class="chart-data"><summary>View daily counts</summary>${table([{label:'Date',key:'date'},...state.metrics.map(m=>({label:metrics[m][0],num:true,render:r=>num(r[m])}))],rows)}</details>`; }
function insightsList(rows,limit=3) {if(!rows?.length)return empty('More activity will reveal patterns','Insights appear when there is enough comparable activity to support them.');return `<div class="insight-list">${rows.slice(0,limit).map(r=>`<article class="insight"><span class="insight-icon" aria-hidden="true">${r.type==='positive'?'↗':r.type==='warning'?'!':'✧'}</span><div><h3>${escape(typeof r==='string'?r:r.title)}</h3>${r.detail?`<p>${escape(r.detail)}</p>`:''}${r.tab?makeAction('insight',r.id,'Explore report →','text-button'):''}</div></article>`).join('')}</div>`; }
function leadColumns(compact=false){return [{label:'Lead',render:l=>makeAction('lead',l.id,`<span class="contact-cell"><span class="row-avatar">${escape((l.name||l.email||'A').split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase())}</span><span>${escape(l.name||l.email)}<span class="row-secondary">${escape(l.name?l.company||l.email:l.company||l.country||'')}</span></span>`)},{label:'Simulator',render:l=>escape(l.simulator_interest||l.simulator_category||'Not selected')},{label:'Source',render:l=>escape(l.latest_source||l.first_source||'Unknown')},{label:'Intent',num:true,render:l=>score(l.intentScore??l.intent_score)},{label:'Status',render:l=>badge(l.status)},...(!compact?[{label:'Newsletter',render:l=>l.marketing_consent?badge('OPTED IN','green'):badge('NO CONSENT','neutral')},{label:'Last activity',render:l=>date(l.last_seen,true)}]:[])];}
function campaignColumns(){return [{label:'Campaign',render:r=>makeAction('filter',r.name,escape(r.name),'row-link','data-dimension="campaign"')},{label:'Visitors',num:true,key:'visitors',render:r=>num(r.visitors)},{label:'Returning',num:true,render:r=>num(r.returning)},{label:'Starts',num:true,render:r=>num(r.starts)},{label:'Completed',num:true,render:r=>num(r.completed)},{label:'Emails',num:true,render:r=>num(r.emails)},{label:'Enquiries',num:true,render:r=>num(r.enquiries)},{label:'Enquiry rate',num:true,render:r=>pct(r.conversion)},{label:'Configured value',num:true,render:r=>values(r.valueByCurrency)}];}
function simulatorTable(rows){return table([{label:'Simulator',render:r=>makeAction('filter',r.name,escape(r.name),'row-link','data-dimension="category"')},{label:'Visitors',num:true,render:r=>num(r.visitors)},{label:'Completed',num:true,render:r=>num(r.completed)},{label:'Emails',num:true,render:r=>num(r.emails)},{label:'Sent',num:true,render:r=>num(r.emailed)},{label:'Enquiries',num:true,render:r=>num(r.enquiries)},{label:'Enquiry rate',num:true,render:r=>pct(r.conversion)}],rows);}
function configTable(rows){return table([{label:'Configuration',render:c=>makeAction('configuration',c.id,escape(c.id))},{label:'Simulator',render:c=>`${escape(c.simulator_model||c.simulator_category||'Not selected')}<span class="row-secondary">${escape(human(c.configurator_type))}</span>`},{label:'Source',render:c=>escape(c.source||'Unknown')},{label:'Potential value',num:true,render:c=>money(c.estimated_price,c.currency)},{label:'Emailed',render:c=>badge(c.emailed?'SENT':'NOT SENT',c.emailed?'green':'neutral')},{label:'Created',render:c=>date(c.created_at,true)}],rows,{caption:'Potential Configured Value is an estimate, not sales revenue. Currencies remain separate.'});}

function renderOverview(){const r=state.report;return kpis([['Unique visitors','visitors',null,'Distinct anonymous browser identifiers in this period.'],['Returning visitors','returningVisitors',null,'Visitors with a recorded visit before this period or an earlier session.'],['Configurator starts','configuratorStarts'],['Configurations','completed'],['Emails captured','leads'],['Enquiries','enquiries']])+panel('Activity over time',renderChart(r.daily),{description:'Follow the path from attention to action.'})+'<div class="grid overview-middle" style="margin-top:20px">'+panel('Website conversion funnel',funnel(r.funnels.website),{description:'How recorded sessions progress toward commercial interest.',action:makeAction('nav','funnels','Full report ↗','text-button')})+panel('Traffic sources',breakdown(r.sources,'source'),{description:'Where your visitors first arrive.',action:makeAction('nav','traffic','View traffic ↗','text-button')})+'</div><div class="grid two">'+panel('Configurator performance',table([{label:'Configurator',render:x=>makeAction('configurator',x.name,`${escape(x.name==='led'?'LED':'Projection')}<span class="row-secondary">Visual systems</span>`)},{label:'Starts',num:true,render:x=>num(x.starts)},{label:'Completed',num:true,render:x=>num(x.completed)},{label:'Completion',num:true,render:x=>pct(rate(x.completed,x.starts))}],[['led',r.funnels.led],['projection',r.funnels.projection]].map(([name,f])=>({name,starts:f.find(x=>/start/i.test(x.key||x.label))?.count||0,completed:f.find(x=>/complet/i.test(x.key||x.label))?.count||0}))),{table:true,description:'From first interaction to completed specification.'})+panel('Simulator interest',breakdown(r.categories,'category','visitors','var(--blue)'),{description:'The markets exploring your products.',action:makeAction('nav','configurators','Explore ↗','text-button')})+'</div><div class="grid">'+panel('Campaign performance',table(campaignColumns(),r.campaigns.slice(0,5)),{table:true,description:'Commercial outcomes, alongside visitor volume.',action:makeAction('nav','campaigns','All campaigns ↗','text-button')})+panel('High-intent leads',table(leadColumns(true),r.leads.filter(l=>(l.intentScore??l.intent_score)>=60).slice(0,5)),{table:true,description:'People showing several signs of serious interest.',action:makeAction('nav','leads','All leads ↗','text-button')})+panel('Latest insights',insightsList(r.insights),{description:'Patterns in your selected period.',action:makeAction('nav','insights','All insights ↗','text-button')})+'</div>'+panel('Additional measurements',`<div class="grid three">${[['Website',[['Sessions','sessions'],['Page views','pageViews'],['Average session duration','avgSessionDuration',duration],['Pages per session','pagesPerSession',dec]]],['Configurators & leads',[['LED starts','ledStarts'],['Projection starts','projectionStarts'],['Configurations emailed','emailed'],['Newsletter subscribers','subscribers'],['High-intent leads','highIntent']]],['Conversion',[['Visitor → configurator','visitorToConfigurator',pct],['Configurator → completed','configuratorToCompleted',pct],['Completed → email captured','completedToEmail',pct],['Email captured → enquiry','emailToEnquiry',pct]]]].map(([title,items])=>`<div><h3 class="section-label" style="margin-top:0">${title}</h3>${items.map(([label,key,format])=>`<div class="stat-line"><span>${escape(label)}</span><div><strong>${format?format(r.metrics[key]):num(r.metrics[key])}</strong>${state.filters.compare?`<div class="kpi-delta">${comparison(key)}</div>`:''}</div></div>`).join('')}</div>`).join('')}</div>`);}
function renderTraffic(){const r=state.report;return kpis([['Unique visitors','visitors'],['Returning visitors','returningVisitors'],['Sessions','sessions'],['Page views','pageViews'],['Avg session','avgSessionDuration',duration],['Pages / session','pagesPerSession',dec]])+'<div class="grid two">'+panel('Traffic sources',breakdown(r.sources,'source','visitors','var(--accent)',10),{description:'All sources preserve their recorded attribution.'})+panel('Country',breakdown(r.countries,'country','visitors','var(--blue)',10),{description:'Coarse location when available; unknown stays unknown.'})+'</div><div class="grid">'+panel('Page performance',table([{label:'Page',render:p=>makeAction('page',p.url,`${escape(p.title||p.url)}<span class="row-secondary">${escape(p.url)}</span>`)},{label:'Visitors',num:true,render:p=>num(p.visitors)},{label:'Returning',num:true,render:p=>num(p.returning)},{label:'Sessions',num:true,render:p=>num(p.sessions)},{label:'Views',num:true,render:p=>num(p.views)},{label:'Avg engagement',num:true,render:p=>duration(p.avgTime)},{label:'Scroll depth',num:true,render:p=>pct(p.scrollDepth)},{label:'Entry rate',num:true,render:p=>pct(p.entryRate)},{label:'Exit rate',num:true,render:p=>pct(p.exitRate)}],r.pages,{caption:'Select a page to inspect navigation, engagement and audience.'}),{table:true,description:'Every recorded public page, with useful engagement detail.'})+panel('Device performance',table([{label:'Device',render:d=>makeAction('filter',d.name,escape(d.name),'row-link','data-dimension="device"')},{label:'Visitors',num:true,render:d=>num(d.visitors)},{label:'Starts',num:true,render:d=>num(d.starts)},{label:'Completed',num:true,render:d=>num(d.completed)},{label:'Completion rate',num:true,render:d=>pct(rate(d.completed,d.starts))},{label:'Emails',num:true,render:d=>num(d.emails)},{label:'Enquiries',num:true,render:d=>num(d.enquiries)}],r.devices),{table:true,description:'Compare configuration completion across desktop, mobile and tablet.'})+'</div>';}
function renderFunnels(){const r=state.report;return '<div class="grid two">'+panel('LED configurator',funnel(r.funnels.led,'led',true),{description:'An ordered session funnel. Steps retain their recorded version.'})+panel('Projection configurator',funnel(r.funnels.projection,'projection',true),{description:'From room geometry to projector specification.'})+'</div><div class="grid two">'+panel('Website funnel',funnel(r.funnels.website,'website',true),{description:'Ordered sessions reaching each commercial milestone.'})+panel('Biggest drop-off',largestDropoff(),{description:'Inspect the sessions behind the largest fall in progress.'})+'</div>'+panel('Funnel by traffic source',table([{label:'Source',render:s=>makeAction('filter',s.name,escape(s.name),'row-link','data-dimension="source"')},{label:'Visitors',num:true,render:s=>num(s.visitors)},{label:'Starts',num:true,render:s=>num(s.starts)},{label:'Completed',num:true,render:s=>num(s.completed)},{label:'Emails',num:true,render:s=>num(s.emails)},{label:'Enquiries',num:true,render:s=>num(s.enquiries)},{label:'Enquiry rate',num:true,render:s=>pct(s.conversion)}],r.sources),{table:true,description:'Judge sources by what visitors do after arriving.'});}
function largestDropoff(){const candidates=['led','projection'].flatMap(type=>state.report.funnels[type].slice(1).map((step,i)=>({...step,type,index:i+1}))).filter(s=>s.lost>0).sort((a,b)=>b.lost-a.lost);if(!candidates.length)return empty('No observed drop-off','Recorded sessions need to progress through the configurator before a drop-off can be measured.');const s=candidates[0];return `<div class="eyebrow">${escape(s.type==='led'?'LED':'PROJECTION')}</div><h3 style="font-size:19px;line-height:1.5;font-weight:500">${escape(state.report.funnels[s.type][s.index-1]?.label||'Previous step')} → ${escape(s.label)}</h3><div class="metric-pair"><strong>${num(s.lost)}</strong><span>sessions did not continue · ${pct(s.dropPct)}</span></div><p class="panel-note">In-progress sessions can still convert. Final abandonment is inferred only after 30 minutes without activity.</p>${makeAction('dropoff',`${s.type}:${s.index}`,'Inspect affected sessions ↗','button small', 'style="margin-top:19px"')}`;}
function renderConfigurators(){const r=state.report;const type=state.filters.configurator!=='All'?String(state.filters.configurator).toLowerCase():state.configuratorTab;state.configuratorTab=type;const f=r.funnels[type]||[];const configs=r.configurations.filter(c=>String(c.configurator_type).toLowerCase()===type);const opens=f[0]?.count||0,starts=f.find(x=>/start/i.test(x.key||x.label))?.count||0,completed=f.find(x=>/complet/i.test(x.key||x.label))?.count||0,email=f.find(x=>x.key==='emails')?.count||0,sent=r.configuratorMetrics?.[type]?.emailed??(f.find(x=>/emailed|sent/i.test(x.key||x.label))?.count||0);const preferences=r.preferences||{};return `<div class="tabbar" role="tablist" aria-label="Configurator type">${['led','projection'].map(t=>`<button role="tab" aria-selected="${t===type}" class="tab-button ${t===type?'active':''}" data-action="configurator-tab" data-value="${t}">${t==='led'?'LED configurator':'Projection configurator'}</button>`).join('')}</div><div class="inline-metrics config-metrics">${[['Visitors',opens],['Starts',starts],['Completed',completed],['Emailed',sent],['Emails captured',email],['Completion rate',pct(rate(completed,starts))]].map(([label,value])=>`<div class="inline-metric"><span>${label}</span><strong>${typeof value==='number'?num(value):value}</strong></div>`).join('')}</div><div class="grid two">${panel(type==='led'?'LED conversion funnel':'Projection conversion funnel',funnel(f,type,true),{description:'Ordered sessions · hover percentages for both denominators.'})}${panel('Simulator commercial performance',simulatorTable(r.categories),{table:true,description:'The selected report population, grouped by simulator category.'})}</div><div class="preference-grid" style="margin-bottom:20px">${(type==='led'?[['Screen shape','screenTypes'],['Pixel pitch','pixelPitches'],['Horizontal field of view','fieldOfView']]:[['Projector type','projectorTypes'],['Mount style','mountStyles'],['Screen geometry','screenTypes']]).map(([title,key])=>panel(title,preferenceList(preferences[key]),{description:'Recorded selections within your current filters.'})).join('')}</div><div class="grid">${panel('Saved configurations',configTable(configs),{table:true,description:`${num(configs.length)} recorded ${type==='led'?'LED':'projection'} configurations · open any configuration for its full specification.`})}${panel('Source quality',table([{label:'Source',render:s=>makeAction('filter',s.name,escape(s.name),'row-link','data-dimension="source"')},{label:'Starts',num:true,render:s=>num(s.starts)},{label:'Completed',num:true,render:s=>num(s.completed)},{label:'Emails',num:true,render:s=>num(s.emails)},{label:'Enquiries',num:true,render:s=>num(s.enquiries)},{label:'Configured value',num:true,render:s=>values(s.valueByCurrency)}],r.sources),{table:true,description:'Use the global configurator filter to narrow every measurement to one product.'})}</div>`;}
function preferenceList(rows){if(!rows?.length)return empty('No selections recorded','These preferences will appear when their values are supplied by a configurator.');const max=Math.max(...rows.map(r=>r.count||0),1);return `<div class="breakdown-list">${rows.slice(0,7).map(r=>`<div class="bar-row"><span>${escape(r.name)}</span><span class="bar-track"><span class="bar-fill" style="width:${r.count/max*100}%;background:var(--blue)"></span></span><span class="bar-value" title="${num(r.count)} selections">${pct(r.pct)}</span></div>`).join('')}</div><p class="panel-note">${num(rows.reduce((a,r)=>a+(r.count||0),0))} recorded selections</p>`;}
function renderLeads(){const r=state.report;let leads=r.leads;if(state.leadTab==='newsletter')leads=leads.filter(l=>l.marketing_consent===true);return `<div class="tabbar" role="tablist" aria-label="Lead list"><button class="tab-button ${state.leadTab==='all'?'active':''}" role="tab" aria-selected="${state.leadTab==='all'}" data-action="lead-tab" data-value="all">All leads <span class="faint">${num(r.leads.length)}</span></button><button class="tab-button ${state.leadTab==='newsletter'?'active':''}" role="tab" aria-selected="${state.leadTab==='newsletter'}" data-action="lead-tab" data-value="newsletter">Newsletter subscribers <span class="faint">${num(r.leads.filter(l=>l.marketing_consent===true).length)}</span></button></div>${panel(state.leadTab==='newsletter'?'Newsletter subscribers':'Leads',table(leadColumns(),leads,{caption:state.leadTab==='newsletter'?'Only people whose latest recorded marketing consent is explicitly true.':'Email capture and marketing consent are separate. Open a lead to manage status and notes.'}),{table:true,description:state.leadTab==='newsletter'?'Explicit opt-ins, with their recorded consent evidence.':'Volunteered contacts linked to their anonymous history.',action:makeAction('export-leads',state.leadTab,'↓ Export CSV','button small')})}<div class="grid" style="margin-top:20px">${panel('High-intent visitors',table([{label:'Visitor',render:j=>makeAction(j.lead?'lead':'journey',j.lead?.id||j.visitor_id,escape(j.lead?.email||j.visitor_id))},{label:'Country',key:'country'},{label:'Simulator',key:'category'},{label:'Source',key:'source'},{label:'Intent score',num:true,render:j=>score(j.intentScore)},{label:'Latest activity',render:j=>date(j.lastActivity,true)}],r.journeys.filter(j=>j.intentScore>=60).slice(0,50)),{table:true,description:'Anonymous visitors stay anonymous until they volunteer contact details.'})}</div>`;}
function renderCampaigns(){const r=state.report;return panel('Campaign performance',table(campaignColumns(),r.campaigns,{caption:'Potential Configured Value is not revenue. Each currency is reported separately.'}),{table:true,description:'Campaign parameters and ref codes are retained together.',action:makeAction('export-campaigns','','↓ Export CSV','button small')})+'<div class="grid" style="margin-top:20px">'+panel('Campaign quality',table([{label:'Campaign',render:c=>makeAction('filter',c.name,escape(c.name),'row-link','data-dimension="campaign"')},{label:'Start rate',num:true,render:c=>pct(rate(c.starts,c.visitors))},{label:'Completion rate',num:true,render:c=>pct(rate(c.completed,c.starts))},{label:'Email capture rate',num:true,render:c=>pct(rate(c.emails,c.completed))},{label:'Enquiry rate',num:true,render:c=>pct(c.conversion)},{label:'Average intent',num:true,render:c=>dec(c.avgIntent)},{label:'Average configured value',num:true,render:c=>values(c.avgValueByCurrency)}],r.campaigns),{table:true,description:'Start = starts ÷ visitors · completion = completed ÷ starts · email = captured ÷ completed · enquiry = enquiries ÷ visitors.'})+'</div><div class="grid two">'+panel('Sources by enquiries',breakdown([...r.sources].sort((a,b)=>b.enquiries-a.enquiries),'source','enquiries','var(--green)'),{description:'Traffic quality, expressed in commercial actions.'})+panel('Simulator commercial performance',simulatorTable(r.categories),{table:true,description:'Use a source or campaign filter to compare the markets it attracts.'})+'</div>';}
function renderJourneys(){return panel('Visitor journeys',table([{label:'Visitor',render:j=>makeAction('journey',j.visitor_id,`${escape(j.lead?.name||j.lead?.email||j.visitor_id)}<span class="row-secondary">${j.lead?escape(j.visitor_id):'Anonymous visitor'}</span>`)},{label:'Country',key:'country'},{label:'Source',key:'source'},{label:'Simulator',key:'category'},{label:'Events',num:true,render:j=>num(j.events?.length)},{label:'Intent',num:true,render:j=>score(j.intentScore)},{label:'Last activity',render:j=>date(j.lastActivity,true)}],state.report.journeys,{caption:'Journeys connect recorded events from the same first-party browser identifier.'}),{table:true,description:'Select any visitor to see their chronological history.'});}
function renderLive(){const rows=state.report.live||[];return `<div class="action-row" style="justify-content:space-between;margin-bottom:22px"><div class="live-heading"><span class="live-pulse"></span><span style="font-size:20px;font-weight:550">${num(rows.length)} active ${rows.length===1?'visitor':'visitors'}</span></div><span class="small-text faint">${state.mode==='demo'?'Demonstration snapshot':'Refreshes every 30 seconds'}</span></div>${rows.length?`<div class="live-cards">${rows.map(j=>`<article class="live-card"><div class="live-card-top"><span><span class="connection-dot"></span>${escape(j.country||'Unknown country')}</span><span>${escape(human(j.configurator_type||'Website'))}</span></div><h3>${makeAction('journey',j.visitor_id,escape(j.lead?.email||j.visitor_id))}</h3><p>${escape(j.currentPage||j.events?.at(-1)?.page_url||'Unknown page')}</p><p>${escape(j.category||'Simulator not selected')}${j.simulator_model?' · '+escape(j.simulator_model):''}</p><div class="stat-line"><span>Current step</span><strong>${escape(human(j.lastStep||j.events?.at(-1)?.event_name||'Page view'))}</strong></div><div class="stat-line"><span>Source</span><strong>${escape(j.source||'Unknown')}</strong></div></article>`).join('')}</div>`:panel('Active visitors',empty('No visitors active right now','A visitor appears here when their most recent recorded activity is within the past five minutes.'))}`;}
function renderInsights(){const r=state.report;return `<div class="insight-grid">${r.insights.length?r.insights.map(i=>`<div class="insight-card">${insightsList([i],1)}</div>`).join(''):panel('Insights',insightsList([]))}</div><div class="grid" style="margin-top:24px">${panel('Problems & performance',table([{label:'Problem',render:p=>`<span>${escape(human(p.name))}</span><span class="row-secondary">${escape(p.message||'')}</span>`},{label:'Type',render:p=>badge(human(p.type||'error'),p.type==='error'?'red':'amber')},{label:'Page',render:p=>escape(p.page_url)},{label:'Duration',num:true,render:p=>p.duration_ms?`${num(p.duration_ms)} ms`:'—'},{label:'Visitor',render:p=>makeAction('journey',p.visitor_id,escape(p.visitor_id))},{label:'Recorded',render:p=>date(p.timestamp,true)}],r.problems,{emptyTitle:'No problems recorded',emptyDetail:'Captured website errors, failed requests and slow operations will appear here.'}),{table:true,description:'Recorded errors and slow operations in the current population.'})}</div>`;}
function renderSettings(){const settings={...defaultSettings,...state.snapshot.settings,scoring:{...defaultSettings.scoring,...state.snapshot.settings?.scoring},alertThresholds:{...defaultSettings.alertThresholds,...state.snapshot.settings?.alertThresholds}};return `<div class="settings-grid">${panel('Intent scoring',`<p class="settings-note">Each signal contributes once per visitor. Repeated clicks do not inflate intent. High intent begins at 60 points; sales lead at 80.</p><form id="scoring-form" class="settings-form">${Object.entries(settings.scoring).map(([key,value])=>`<div class="settings-row"><label for="score-${attr(key)}">${escape(human(key))}</label><input id="score-${attr(key)}" name="${attr(key)}" type="number" min="0" max="100" step="1" value="${Number(value)||0}" aria-label="Points for ${attr(human(key))}"></div>`).join('')}<button type="submit" class="button primary">Save scoring rules</button></form>`,{description:'A practical measure of demonstrated commercial interest.'})}<div class="grid">${panel('Collection status',`<div class="stat-line"><span>Workspace</span><strong>${state.mode==='demo'?'Demonstration':'Connected reports'}</strong></div><div class="stat-line"><span>Recorded events loaded</span><strong>${num(state.snapshot.events?.length)}</strong></div><div class="stat-line"><span>Last refresh</span><strong>${date(state.lastUpdated,true)}</strong></div><div class="stat-line"><span>Reporting timezone</span><strong>Europe/Paris</strong></div><div class="stat-line"><span>Session timeout</span><strong>30 minutes inactive</strong></div><p class="settings-note" style="margin-top:15px">This workspace is isolated from the public website. Live tracking starts only after the supplied collector and configurator hooks are deliberately installed. Past visits cannot be reconstructed.</p><div class="code-block">${escape(config.endpoint)}</div>`,{description:'One central endpoint for website and configurator events.'})}${panel('Alerts',`<p class="settings-note">Saved thresholds identify in-dashboard signals. External notification delivery is not connected.</p><form id="alerts-form" class="settings-form"><label class="check-label"><input name="enabled" type="checkbox" ${settings.alertsEnabled?'checked':''}>Enable in-dashboard alert signals</label><div class="settings-row"><label for="traffic-alert">Traffic increase <small>Compared with previous period, %</small></label><input id="traffic-alert" name="trafficIncreasePct" type="number" min="1" max="1000" value="${Number(settings.alertThresholds.trafficIncreasePct)||50}"></div><div class="settings-row"><label for="conversion-alert">Conversion fall <small>Compared with previous period, %</small></label><input id="conversion-alert" name="conversionDropPct" type="number" min="1" max="100" value="${Number(settings.alertThresholds.conversionDropPct)||30}"></div><div class="settings-row"><label for="value-alert">High configuration value <small>Applied within each recorded currency</small></label><input id="value-alert" name="highValue" type="number" min="0" step="1000" value="${Number(settings.alertThresholds.highValue)||100000}"></div><button class="button" type="submit">Save alert settings</button></form>`,{description:'Optional, and disabled by default.'})}${panel('Demonstration',`<p class="settings-note">Explore every report with fictional visitors and contacts. Demo edits stay in this browser and never reach the real database.</p><div class="action-row">${makeAction('demo','','Open demo','button')}${state.mode==='demo'?makeAction('reset-demo','','Reset demo edits','button'):''}</div>`)}${panel('Data retention & attribution',`<p class="settings-note">No automatic analytics deletion is enabled. First-touch attribution stays attached to a visitor; each session retains its latest source and full campaign parameters.</p><p class="settings-note">Newsletter exports require explicit opt-in. Configurations and customer contact details remain separate from anonymous event properties.</p>`)}</div></div>`;}

function render(){if(!state.snapshot)return;try{state.report=buildReport(state.snapshot,state.filters,new Date());}catch(error){$('#content').innerHTML=panel('Report unavailable',empty('We could not calculate this report',error.message));return;}const r=state.report;const item=nav.find(n=>n[0]===state.tab)||nav[0];$('#breadcrumb-page').textContent=item[1];$('#page-title').textContent=item[1];$('#page-eyebrow').textContent=descriptions[state.tab][0];$('#page-description').textContent=descriptions[state.tab][1];$('#primary-nav').innerHTML=nav.map(([key,label,path])=>`<button class="nav-button ${state.tab===key?'active':''}" data-action="nav" data-value="${key}" ${state.tab===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${path}</svg></span>${label}${key==='live'&&r.live.length?`<span class="nav-count">${num(r.live.length)}</span>`:''}</button>`).join('');$('#range-label').textContent=`${r.range?.from||''} — ${r.range?.to||''} · Europe/Paris`;$('#comparison-label').textContent=state.filters.compare?`Compared with ${r.range?.previousFrom||'previous period'} — ${r.range?.previousTo||''}`:'';$('#content').innerHTML=({overview:renderOverview,traffic:renderTraffic,funnels:renderFunnels,configurators:renderConfigurators,leads:renderLeads,campaigns:renderCampaigns,journeys:renderJourneys,live:renderLive,insights:renderInsights,settings:renderSettings}[state.tab]||renderOverview)();$('#last-updated').textContent=`${state.mode==='demo'?'Demo data · ':''}Updated ${date(state.lastUpdated,true)}`;updateFilterCounts();wireChart();updateBanner();}
function wireChart(){const chart=$('#activity-chart');if(!chart)return;const hover=$('.chart-hover',chart);chart.addEventListener('pointermove',e=>{const rect=chart.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(e.clientX-rect.left-rect.width*.035)/(rect.width*.955))),rows=state.report.daily||[],i=Math.round(ratio*(rows.length-1)),row=rows[i];if(!row)return;const labels={visitors:'Visitors',sessions:'Sessions',pageViews:'Page views',starts:'Starts',completed:'Completed',leads:'Leads',enquiries:'Enquiries'};hover.innerHTML=`<strong>${escape(row.date)}</strong>${state.metrics.map(m=>`<div>${labels[m]} <span style="float:right;margin-left:20px">${num(row[m])}</span></div>`).join('')}`;hover.hidden=false;hover.style.left=`${Math.min(Math.max(0,e.clientX-rect.left+12),rect.width-hover.offsetWidth-8)}px`;hover.style.top='8px';});chart.addEventListener('pointerleave',()=>hover.hidden=true);}
function updateFilterCounts(){const count=Object.entries(state.filters).filter(([key,value])=>!['preset','from','to','compare','query'].includes(key)&&value!=='All').length;$('#filter-count').textContent=count;$('#filter-count').hidden=!count;$('#clear-filters').hidden=!count&&!state.filters.query;}
function filterOptions(){const r=buildReport(state.snapshot,{...filterDefaults,preset:'This Year'},new Date());const options=r.options||{};const categories=options.categories||[];$('#category-filter').innerHTML='<option value="All">All simulators</option>'+categories.map(v=>`<option ${state.filters.category===v?'selected':''} value="${attr(v)}">${escape(v)}</option>`).join('');const fields=[['source','Traffic source',options.sources],['campaign','Campaign',options.campaigns],['country','Country',options.countries],['device','Device',options.devices],['model','Simulator model',options.models],['configurator','Configurator',options.configurators],['visitorType','Visitor type',['New','Returning']],['identity','Identity',['Known','Anonymous']],['status','Lead status',options.statuses?.length?options.statuses:statuses],['intent','Intent level',options.intents?.length?options.intents:['Low','Interested','Engaged','High Intent','Sales Lead']]];$('#advanced-filters').innerHTML=fields.map(([key,label,values])=>`<label>${label}<select data-filter="${key}"><option value="All">All</option>${(values||[]).map(v=>`<option value="${attr(v)}" ${state.filters[key]===v?'selected':''}>${escape(v)}</option>`).join('')}</select></label>`).join('');}
function setFilter(dimension,value){state.filters[dimension]=value;const select=dimension==='category'?$('#category-filter'):$(`[data-filter="${dimension}"]`);if(select)select.value=value;state.tab=dimension==='category'?'traffic':dimension==='campaign'?'campaigns':dimension==='source'?'journeys':state.tab;render();closeDrawer();$('#sidebar').classList.remove('open');toast(`Showing ${value}`);}
function openDrawer(title,body,eyebrow='DETAIL'){state.drawerFocus=document.activeElement;$('#drawer-title').textContent=title;$('#drawer-eyebrow').textContent=eyebrow;$('#drawer-content').innerHTML=body;$('#detail-drawer').hidden=false;$('#drawer-backdrop').hidden=false;document.body.style.overflow='hidden';$('#detail-drawer').focus();}
function closeDrawer(){if($('#detail-drawer').hidden)return;$('#detail-drawer').hidden=true;$('#drawer-backdrop').hidden=true;document.body.style.overflow='';if(state.drawerFocus?.isConnected)state.drawerFocus.focus();}
function eventTimeline(events){if(!events?.length)return empty('No recorded journey');return `<ol class="timeline">${[...events].sort((a,b)=>new Date(a.timestamp)-new Date(b.timestamp)).map(e=>`<li><time datetime="${attr(e.timestamp)}">${escape(date(e.timestamp,true))}</time><strong>${escape(human(e.event_name))}</strong><p>${escape(e.page_url||'')}${[e.properties?.simulator_category,e.properties?.simulator_model,e.properties?.screen_type,e.properties?.pixel_pitch,e.properties?.projector_type].filter(Boolean).map(v=>' · '+escape(v)).join('')}</p>${e.properties?.configuration_id?makeAction('configuration',e.properties.configuration_id,escape(e.properties.configuration_id),'text-button'):''}</li>`).join('')}</ol>`;}
function showJourney(id){const j=state.report.journeys.find(j=>j.visitor_id===id);if(!j){toast('This visitor has no activity in the selected report.');return;}openDrawer(j.lead?.email||j.visitor_id,section('Visitor',detailGrid([['Anonymous ID',j.visitor_id],['Country',j.country],['Source',j.source],['Simulator',j.category],['Intent score',j.intentScore],['Latest activity',date(j.lastActivity,true)]]))+(j.lead?`<div class="action-row" style="margin-bottom:25px">${makeAction('lead',j.lead.id,'Open lead record ↗','button small')}</div>`:'')+section('Chronological journey',eventTimeline(j.events)),'VISITOR JOURNEY');}
function showLead(id){const l=state.report.leads.find(l=>l.id===id)||state.snapshot.leads.find(l=>l.id===id);if(!l)return toast('This lead is outside the selected report.');const journeys=state.report.journeys.filter(j=>j.lead?.id===l.id||(l.visitor_ids||[]).includes(j.visitor_id));const configs=state.report.configurations.filter(c=>c.lead_id===l.id||(l.visitor_ids||[]).includes(c.visitor_id));openDrawer(l.name||l.email,section('Contact',detailGrid([['Email',l.email],['Name',l.name],['Company',l.company],['Telephone',l.telephone],['Country',l.country],['First recorded visit',date(l.first_seen,true)],['Last activity',date(l.last_seen,true)]]))+section('Attribution',detailGrid([['First source',l.first_source],['First campaign',l.first_campaign],['Latest source',l.latest_source],['Latest campaign',l.latest_campaign]]))+section('Commercial interest',detailGrid([['Simulator',l.simulator_interest],['Intent score',l.intentScore??l.intent_score],['Configurations',configs.length]]))+section('Lead status & notes',`<form id="lead-edit-form" class="detail-form" data-lead="${attr(l.id)}"><label>Status<select name="status">${statuses.map(s=>`<option ${String(l.status).toUpperCase()===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Notes<textarea name="notes" maxlength="5000" placeholder="Add a useful note for the next conversation…">${escape(l.notes||'')}</textarea></label><div class="action-row"><button class="button primary" type="submit">Save lead</button><span class="small-text faint">${state.mode==='demo'?'Saved in this demo only':'Saved to reporting database'}</span></div></form>`)+section('Marketing consent',detailGrid([['Newsletter',l.marketing_consent===true?'Explicit opt-in':'No current consent'],['Consent recorded',date(l.consent_timestamp,true)],['Wording version',l.consent_text_version],['Source page',l.consent_source]]))+section('Saved configurations',configs.length?configs.map(c=>makeAction('configuration',c.id,`<strong>${escape(c.id)}</strong><p>${escape(c.simulator_model||c.simulator_category||'Not selected')} · ${money(c.estimated_price,c.currency)} · ${date(c.created_at)}</p>`,'config-card')).join(''):empty('No configurations in this period'))+section('Recorded journey',eventTimeline(l.events||journeys.flatMap(j=>j.events))),'LEAD RECORD');}
function showConfiguration(id){const c=state.report.configurations.find(c=>c.id===id)||state.snapshot.configurations.find(c=>c.id===id);if(!c)return toast('This configuration was not found in the loaded data.');const specification=c.configuration_json||c.properties||{};openDrawer(c.id,section('Configuration',detailGrid([['Configurator',human(c.configurator_type)],['Simulator category',c.simulator_category],['Simulator model',c.simulator_model],['Visitor',c.visitor_id],['Created',date(c.created_at,true)],['Emailed',c.emailed?'Yes':'No'],['Potential Configured Value',c.estimated_price===null?'Not quoted':money(c.estimated_price,c.currency)],['Source',c.source],['Campaign',c.campaign]]))+section('Specification',`<pre class="code-block">${escape(JSON.stringify(specification,null,2))}</pre>`)+`<p class="settings-note">Potential Configured Value is an estimate generated by the configurator. It is not sales revenue.</p>${makeAction('journey',c.visitor_id,'Open visitor journey ↗','button small')}`,'SAVED CONFIGURATION');}
function showPage(url){const p=state.report.pages.find(p=>p.url===url);if(!p)return;const listRows=x=>Array.isArray(x)?x.map(v=>typeof v==='string'?{name:v,count:''}:v):Object.entries(x||{}).map(([name,count])=>({name,count}));const smallList=x=>listRows(x).length?listRows(x).map(r=>`<div class="stat-line"><span>${escape(r.name||r.url||r.page||'Unknown')}</span><strong>${r.count===''?'Recorded':num(r.count??r.visitors??r.views)}</strong></div>`).join(''):empty('No navigation recorded');openDrawer(p.title||p.url,section('Page',detailGrid([['URL',p.url],['Visitors',p.visitors],['Returning visitors',p.returning],['Sessions',p.sessions],['Page views',p.views],['Average engagement',duration(p.avgTime)],['Average scroll depth',pct(p.scrollDepth)],['Entry rate',pct(p.entryRate)],['Exit rate',pct(p.exitRate)]]))+section('Previous page',smallList(p.previousPages))+section('Next page',smallList(p.nextPages))+section('Devices',smallList(p.devices))+section('Countries',smallList(p.countries))+section('Sources',smallList(p.sources)),'PAGE ANALYTICS');}
function showDropoff(value){const [type,indexString]=value.split(':');const index=Number(indexString);const rows=state.report.funnels[type]||[];const current=rows[index],previous=rows[index-1];if(!current||!previous)return;const currentIds=new Set(current.sessionIds||[]);const missing=(previous.sessionIds||[]).filter(id=>!currentIds.has(id));const journeys=state.report.journeys.filter(j=>j.events.some(e=>missing.includes(e.session_id)));openDrawer(`${previous.label} → ${current.label}`,`<p class="settings-note">${num(current.lost)} sessions did not reach this step during the selected period. A session is only considered abandoned after 30 minutes without activity; recent sessions may still continue.</p>`+table([{label:'Visitor',render:j=>makeAction('journey',j.visitor_id,escape(j.lead?.email||j.visitor_id))},{label:'Source',key:'source'},{label:'Last activity',render:j=>date(j.lastActivity,true)}],journeys,{emptyTitle:'No matching session detail'}),'FUNNEL DROP-OFF');}
function downloadCSV(rows,columns,name){const cell=value=>{let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const csv='\uFEFF'+[columns.map(c=>cell(c.label)).join(','),...rows.map(row=>columns.map(c=>cell(typeof c.value==='function'?c.value(row):row[c.value])).join(','))].join('\r\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download=`simworx-${name}-${state.report.range?.to||'report'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${rows.length} ${name} records in the current report.`);}
function exportLeads(type){const rows=state.report.leads.filter(l=>type!=='newsletter'||l.marketing_consent===true);const columns=type==='newsletter'?[['Email','email'],['Name','name'],['Company','company'],['Country','country'],['Signup date','consent_timestamp'],['Simulator interest','simulator_interest'],['Marketing source','first_source']]:[['Email','email'],['Name','name'],['Company','company'],['Telephone','telephone'],['Country','country'],['Simulator interest','simulator_interest'],['Last configuration',l=>state.report.configurations.filter(c=>c.lead_id===l.id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0]?.id||''],['Lead status','status'],['Intent score',l=>l.intentScore??l.intent_score],['Campaign','latest_campaign'],['Last activity','last_seen']];downloadCSV(rows,columns.map(([label,value])=>({label,value})),type==='newsletter'?'newsletter-subscribers':'leads');}
function saveDemoEdits(){try{localStorage.setItem(config.demoEditsKey,JSON.stringify({settings:state.snapshot.settings,leads:state.snapshot.leads.map(l=>({id:l.id,status:l.status,notes:l.notes}))}));}catch{}}
async function saveSettings(update){const next={...state.snapshot.settings,...update};if(state.mode==='demo'){state.snapshot.settings=next;saveDemoEdits();}else{await api('settings',{settings:next});state.snapshot.settings=next;}render();toast(state.mode==='demo'?'Demo settings saved in this browser.':'Reporting settings saved.');}
async function enterDemo(){state.lastError=null;state.mode='demo';state.token=null;state.expiresAt=null;state.snapshot=demoSnapshot(new Date());try{const edits=JSON.parse(localStorage.getItem(config.demoEditsKey)||'null');if(edits){state.snapshot.settings={...state.snapshot.settings,...edits.settings};for(const lead of state.snapshot.leads){const edit=edits.leads?.find(l=>l.id===lead.id);if(edit)Object.assign(lead,edit);}}}catch{}state.lastUpdated=new Date().toISOString();showApp();banner('Demonstration data — all visitors, contacts and commercial results shown here are fictional. Live website tracking has not been enabled.',makeAction('return-login','','Open live reports →','text-button'));filterOptions();render();}
function showApp(){$('#login-screen').hidden=true;$('#app-shell').hidden=false;$('#data-mode').textContent=state.mode==='demo'?'DEMO WORKSPACE':'LIVE DATA';$('#data-mode').classList.toggle('demo',state.mode==='demo');$('#sidebar-status').textContent=state.mode==='demo'?'Demonstration workspace':'Reporting service connected';}
async function loadSnapshot(){const version=++state.requestVersion;$('#refresh').disabled=true;try{const data=await api('snapshot');if(version!==state.requestVersion)return;state.lastError=null;state.snapshot=data.snapshot||data;state.snapshot.events ||= [];state.snapshot.leads ||= [];state.snapshot.configurations ||= [];state.snapshot.settings ||= {};state.snapshot.meta ||= {};state.lastUpdated=new Date().toISOString();showApp();filterOptions();if(!state.snapshot.events.length)banner('The reports workspace is ready. No live website events have been collected yet; tracking remains separate from the public site.',makeAction('demo','','Explore demo →','text-button'));else banner('');render();}catch(error){if(!$('#app-shell').hidden){state.lastError=error.message;updateBanner();}else $('#login-error').textContent=`${error.message} You can explore the demonstration while the service is being connected.`;}finally{$('#refresh').disabled=false;}}
async function signOut(remote=true){if(remote&&state.mode!=='demo'&&state.token)try{await api('logout');}catch{}state.requestVersion++;sessionClear();state.token=null;state.expiresAt=null;state.snapshot=null;state.report=null;closeDrawer();$('#login-screen').hidden=false;$('#app-shell').hidden=true;$('#pin').value='';$('#login-error').textContent='';$('#pin').focus();}

$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button',e.currentTarget);button.disabled=true;$('#login-error').textContent='';try{const result=await api('login',{pin:$('#pin').value});state.mode='live';state.token=result.token;state.expiresAt=result.expires_at;sessionSave();await loadSnapshot();}catch(error){$('#login-error').textContent=error.message;}finally{button.disabled=false;}});
$('#demo-login').addEventListener('click',enterDemo);
$('#logout').addEventListener('click',()=>signOut());
$('#refresh').addEventListener('click',()=>state.mode==='demo'?(state.lastUpdated=new Date().toISOString(),render(),toast('Demonstration refreshed.')):loadSnapshot());
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#filters-toggle').addEventListener('click',()=>{const expanded=$('#advanced-filters').hidden;$('#advanced-filters').hidden=!expanded;$('#filters-toggle').setAttribute('aria-expanded',String(expanded));});
$('#clear-filters').addEventListener('click',()=>{const {preset,from,to,compare}=state.filters;state.filters={...filterDefaults,preset,from,to,compare};$('#global-search').value='';filterOptions();render();});
$('#date-preset').addEventListener('change',e=>{state.filters.preset=e.target.value;$('#custom-dates').hidden=e.target.value!=='Custom Date Range';if(!$('#custom-dates').hidden){if(!$('#date-from').value)$('#date-from').value=state.report.range.from;if(!$('#date-to').value)$('#date-to').value=state.report.range.to;state.filters.from=$('#date-from').value;state.filters.to=$('#date-to').value;}render();});
$('#apply-dates').addEventListener('click',()=>{const from=$('#date-from').value,to=$('#date-to').value;if(!from||!to||from>to){$('#date-error').textContent='Choose a valid start and end date.';return;}$('#date-error').textContent='';state.filters.from=from;state.filters.to=to;render();});
$('#compare').addEventListener('change',e=>{state.filters.compare=e.target.checked;render();});
$('#category-filter').addEventListener('change',e=>{state.filters.category=e.target.value;render();});
let searchTimer;$('#global-search').addEventListener('input',e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.filters.query=e.target.value.trim();render();},250);});
$('#advanced-filters').addEventListener('change',e=>{if(e.target.matches('[data-filter]')){state.filters[e.target.dataset.filter]=e.target.value;render();}});
$('#drawer-close').addEventListener('click',closeDrawer);$('#drawer-backdrop').addEventListener('click',closeDrawer);
document.addEventListener('keydown',e=>{if(!$('#detail-drawer').hidden){if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const focusable=$$('button,input,select,textarea,a[href],[tabindex="0"]',$('#detail-drawer')).filter(el=>!el.disabled&&!el.hidden);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#detail-drawer'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}else if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('change',e=>{if(e.target.matches('[data-chart-metric]')){const metric=e.target.dataset.chartMetric;if(e.target.checked)state.metrics.push(metric);else state.metrics=state.metrics.filter(x=>x!==metric);if(!state.metrics.length)state.metrics=['visitors'];render();}});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;const {action,value,dimension}=target.dataset;try{if(action==='nav'){state.tab=value;if(value==='configurators'&&state.filters.configurator==='All'){state.filters.configurator=state.configuratorTab;filterOptions();}closeDrawer();$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});}else if(action==='filter')setFilter(dimension,value);else if(action==='lead')showLead(value);else if(action==='journey')showJourney(value);else if(action==='configuration')showConfiguration(value);else if(action==='page')showPage(value);else if(action==='dropoff')showDropoff(value);else if(action==='configurator'){state.tab='configurators';state.configuratorTab=value;state.filters.configurator=value;filterOptions();render();}else if(action==='configurator-tab'){state.configuratorTab=value;state.filters.configurator=value;filterOptions();render();}else if(action==='lead-tab'){state.leadTab=value;render();}else if(action==='export-leads')exportLeads(value);else if(action==='export-campaigns')downloadCSV(state.report.campaigns,[{label:'Campaign',value:'name'},{label:'Visitors',value:'visitors'},{label:'Starts',value:'starts'},{label:'Completed',value:'completed'},{label:'Emails',value:'emails'},{label:'Enquiries',value:'enquiries'},{label:'Enquiry rate (%)',value:'conversion'},{label:'Configured value by currency',value:r=>JSON.stringify(r.valueByCurrency)}],'campaigns');else if(action==='demo')await enterDemo();else if(action==='return-login')await signOut(false);else if(action==='reset-demo'){try{localStorage.removeItem(config.demoEditsKey);}catch{}await enterDemo();toast('Demonstration edits reset.');}else if(action==='insight'){const insight=state.report.insights.find(i=>i.id===value);if(insight){state.tab=insight.tab||'insights';Object.assign(state.filters,insight.filter||{});filterOptions();render();}}}catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{if(!['lead-edit-form','scoring-form','alerts-form'].includes(e.target.id))return;e.preventDefault();const button=$('button[type=submit]',e.target),form=new FormData(e.target);button.disabled=true;try{if(e.target.id==='lead-edit-form'){const id=e.target.dataset.lead,update={status:String(form.get('status')),notes:String(form.get('notes'))};if(state.mode!=='demo')await api('update_lead',{id,...update});const lead=state.snapshot.leads.find(l=>l.id===id);if(lead)Object.assign(lead,update);if(state.mode==='demo')saveDemoEdits();render();toast(state.mode==='demo'?'Lead saved in this demo only.':'Lead updated.');}else if(e.target.id==='scoring-form'){const scoring=Object.fromEntries([...form.entries()].map(([k,v])=>[k,Math.max(0,Math.min(100,Number(v)||0))]));await saveSettings({scoring});}else{await saveSettings({alertsEnabled:form.get('enabled')==='on',alertThresholds:{trafficIncreasePct:Number(form.get('trafficIncreasePct')),conversionDropPct:Number(form.get('conversionDropPct')),highValue:Number(form.get('highValue'))}});}}catch(error){toast(error.message);}finally{button.disabled=false;}});
setInterval(()=>{if($('#app-shell').hidden)return;if(state.mode!=='demo'&&state.expiresAt&&new Date(state.expiresAt)<=new Date()){signOut(false);$('#login-error').textContent='Your reporting session expired. Enter the PIN to continue.';return;}if(state.tab==='live'){if(state.mode==='demo')render();else loadSnapshot();}},config.refreshInterval);
(async()=>{if(new URLSearchParams(location.search).get('demo')==='1'){await enterDemo();return;}try{const saved=JSON.parse(sessionStorage.getItem(config.sessionKey)||'null');if(saved?.token&&new Date(saved.expires_at)>new Date()){state.token=saved.token;state.expiresAt=saved.expires_at;await loadSnapshot();}else sessionClear();}catch{sessionClear();}})();
